#!/usr/bin/env python3
import hashlib, importlib.util, json, re, time
from pathlib import Path
E=Path('/home/deck/.local/state/rog5-vm-startup-stall-20260919-r1')
W=Path('/home/deck/.local/state/rog5-review-correctness-20260912-r1')
def identity(p):
 h=hashlib.sha256()
 with p.open('rb') as f:
  for b in iter(lambda:f.read(1024*1024),b''):h.update(b)
 return {'path':str(p),'bytes':p.stat().st_size,'sha256':h.hexdigest()}
spec=importlib.util.spec_from_file_location('runner',W/'scripts/host/test-qemu-logind.py');m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)
r={'scope':'Read-only generic ARM64 VM evidence audit; no phone operation or new VM/build','parser':identity(W/'scripts/host/test-qemu-logind.py'),'physical':'NOT RUN','runs':{}}
for name,rel in [('control','startup-multi/vm'),('debug','startup-debug')]:
 d=E/rel;record=json.loads((d/'result.json').read_text());s=(d/'serial.log').read_text(errors='replace')
 clean=re.sub(r'\x1b\[[0-9;:]*m','',s)
 packet=re.search(r'DIAGNOSTIC_UNIT_TIMINGS status=(read|failed)(?: code=(\d+))? bytes=(\d+) hex=([0-9a-f]+)',s)
 raw=bytes.fromhex(packet[4]);assert len(raw)==int(packet[3]); units={}
 for block in raw.decode().strip().split('\n\n'):
  fields=dict(line.split('=',1) for line in block.splitlines());units[fields['Id']]=fields
 durations={key:(int(v['ExecMainExitTimestampMonotonic'])-int(v['ExecMainStartTimestampMonotonic']))/1e6 for key,v in units.items() if int(v.get('ExecMainExitTimestampMonotonic',0)) and int(v.get('ExecMainStartTimestampMonotonic',0))}
 start=time.monotonic()
 try: parsed=m.startup_result(s); parsing={'status':'PASS','units':len(parsed['units'])}
 except ValueError as exc: parsing={'status':'REJECTED','error':str(exc)}
 parsing['seconds']=time.monotonic()-start
 try:m.require_vm_poweroff(s);poweroff=True
 except Exception:poweroff=False
 q=next(x for x in record['steps'] if 'qemu-system-aarch64' in x['command'])
 r['runs'][name]={'result':identity(d/'result.json'),'serial':identity(d/'serial.log'),'overall_status':record['status'],'qemu_seconds':q['duration_seconds'],'qemu_exit':q['exit_status'],'parser_replay':parsing,'query_status':int(packet[2] or 0),'inventory_count':len(units),'missing_units':sorted(set(m.STARTUP_UNITS)-units.keys()),'units':units,'executed_unit_seconds':durations,'rcu_stall_reports':len(re.findall(r'rcu: INFO: .*detected stalls',s)),'normal_poweroff_no_panic':poweroff,'authenticated_scope_cleanup_marker':m.SUCCESS in s,'startup_readiness_marker':'PASS startup-only authenticated readiness; Denial NOT RUN' in s,'pid1_handoff_boottime_seconds':float(re.search(r'OBSERVE pid1-handoff boottime=([0-9.]+)',s)[1]),'unit_transaction_report':re.findall(r'Loaded units and determined initial transaction in ([0-9.]+s)\.',clean),'successful_system_generators':re.findall(r"'/usr/lib/systemd/system-generators/([^']+)' succeeded\.",clean),'successful_environment_generators':re.findall(r"'/usr/lib/systemd/system-environment-generators/([^']+)' succeeded\.",clean)}
 if name=='debug':
  p=re.search(r'DIAGNOSTIC_UNIT_QUERY code=(\d+) bytes=(\d+) hex=([0-9a-f]+)',s);query=bytes.fromhex(p[3]).decode();assert len(query.encode())==int(p[2]);r['runs'][name]['query_stderr']=query
  r['runs'][name]['postrun_input_verification']=[{'path':path,'same':identity(Path(path))==expected} for path,expected in record['inputs'].items()]
r['interpretation']={'overall_debug_failure':'Correct rejection of timed-out incomplete timing inventory; not a VM boot failure or RCU reproduction.','clocks':'Unit timestamps are systemd CLOCK_MONOTONIC microseconds. Handoff is /proc/uptime BOOTTIME; do not subtract across them. QEMU seconds use host monotonic runtime.','generators':'17 system and one environment generators succeeded; no recorded generator duration. The 6.3s message measures unit-loading/initial-transaction work, not generators.','query':'Eight GetAll replies received on authenticated private systemd bus; ninth sysinit.target request was sent and reached PID1, but no reply was recorded before timeout 124. No per-call timestamp permits allocating the eight-second budget to individual calls.','next_observation':'If future independently useful VM runs need earlier-startup timing, query verified packaged Manager monotonic startup properties in a separate bounded call; avoid global debug serial output. Do not extend deadlines or accept partial inventory. If the RCU symptom recurs, correlate host per-vCPU scheduling/progress with guest stack observations.','causality':'Non-reproduction twice does not fix the intermittent stall; global debug adds observer overhead, but its contribution to query timeout is unproved.'}
(E/'debug-audit.json').write_text(json.dumps(r,indent=2)+'\n')
print(json.dumps({'runs':{k:{x:v[x] for x in ['overall_status','qemu_seconds','inventory_count','rcu_stall_reports','executed_unit_seconds','parser_replay']} for k,v in r['runs'].items()},'all_debug_inputs_unchanged':all(x['same'] for x in r['runs']['debug']['postrun_input_verification'])},indent=2))

