from pathlib import Path
import datetime,json,subprocess,time
E=Path(__file__).resolve().parent;D=E/'startup-hwdb-compressed';r=json.loads((D/'started.json').read_text());name=r['container'];pid=int(subprocess.check_output(['podman','inspect','--format','{{.State.Pid}}',name],text=True,timeout=10));P=Path('/proc')/str(pid);assert pid>1
cmd=(P/'cmdline').read_bytes().replace(b'\0',b' ').decode();assert 'qemu-system-aarch64' in cmd and '/Image' in cmd
cgroups=(P/'cgroup').read_text();cgroup=next(line.split(':',2)[2] for line in cgroups.splitlines() if line.startswith('0::'));cg=Path('/sys/fs/cgroup')/cgroup.lstrip('/')
def read(p):
 try:return p.read_text()
 except OSError as e:return dict(error=type(e).__name__,detail=str(e))
rows=[]
for n in range(3):
 row=dict(utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),host_monotonic=time.monotonic(),qemu_pid=pid,cgroup=str(cg),tasks=[],cgroup_values={k:read(cg/k) for k in ['cpu.stat','cpu.pressure','memory.current','memory.events','memory.swap.current']},serial_bytes=(D/'serial.log').stat().st_size)
 for task in sorted((P/'task').iterdir()):row['tasks'].append(dict(tid=int(task.name),comm=read(task/'comm'),stat=read(task/'stat'),schedstat=read(task/'schedstat'),wchan=read(task/'wchan'),syscall=read(task/'syscall')))
 rows.append(row)
 if n<2:time.sleep(1)
(E/'hwdb-live-host.json').write_text(json.dumps(dict(container=name,command=cmd,cgroup=cgroups,samples=rows,scope='Read-only host scheduling/cgroup samples during the same owned VM; no ptrace or phone operation'),indent=2)+'\n');print('Captured',len(rows),'samples of',len(rows[0]['tasks']),'host threads')
